const xml = String(($json && $json.data) || "");
const book = "/addressbook/YOUR-LOGIN%40yandex.ru/1/";
function trimSlash(value) { let out = value; while (out.endsWith("/")) out = out.slice(0, -1); return out; }
const hrefs = [];
const lower = xml.toLowerCase();
let cursor = 0;
while (true) {
  const start = lower.indexOf("href", cursor);
  if (start < 0) break;
  const openEnd = xml.indexOf(">", start);
  if (openEnd < 0) break;
  const closeStart = xml.indexOf("<", openEnd + 1);
  if (closeStart < 0) break;
  const value = xml.slice(openEnd + 1, closeStart).trim();
  if (value) hrefs.push(value);
  cursor = closeStart + 1;
}
const cards = hrefs.filter((href) => href.indexOf("/addressbook/") >= 0 && trimSlash(href) !== trimSlash(book));
const parts = cards.map((href) => "<d:href>" + href + "</d:href>").join("");
const multiget = '<c:addressbook-multiget xmlns:d="DAV:" xmlns:c="urn:ietf:params:xml:ns:carddav">' + '<d:prop><d:getetag/><c:address-data/></d:prop>' + parts + "</c:addressbook-multiget>";
return [{ json: { multiget: multiget, cardCount: cards.length, listStatus: Number(($json && $json.statusCode) || 0) } }];

const body = ($("Contacts request").first().json.body) || {};
const list = $("Build multiget query").first().json || {};
const xml = String(($json && $json.data) || "");

function linesOf(block) {
  const out = [];
  for (const piece of block.split("\n")) {
    let line = piece;
    if (line.length && line.charCodeAt(line.length - 1) === 13) line = line.slice(0, -1);
    if (line.length && (line.startsWith(" ") || line.charCodeAt(0) === 9) && out.length) {
      out[out.length - 1] += line.slice(1);
    } else if (line.length) {
      out.push(line);
    }
  }
  return out;
}

const contacts = [];
for (const chunk of xml.split("BEGIN:VCARD").slice(1)) {
  const item = { name: "", emails: [], phones: [], organization: "" };
  for (const line of linesOf(chunk.split("END:VCARD")[0])) {
    const cut = line.indexOf(":");
    if (cut < 0) continue;
    const key = line.slice(0, cut).split(";")[0].toUpperCase();
    const value = line.slice(cut + 1).trim();
    if (!value) continue;
    if (key === "FN" && !item.name) item.name = value;
    else if (key === "N" && !item.name) {
      const parts = value.split(";");
      const built = [parts[1], parts[0]].filter((part) => part).join(" ");
      if (built) item.name = built;
    }
    else if (key === "EMAIL") item.emails.push(value);
    else if (key === "TEL") item.phones.push(value);
    else if (key === "ORG") item.organization = value.split(";").join(" ");
    else if (key === "TITLE") item.title = value;
  }
  if (item.name || item.emails.length || item.phones.length) contacts.push(item);
}

contacts.sort((left, right) => String(left.name || left.emails[0] || "").localeCompare(String(right.name || right.emails[0] || ""), "ru"));

const action = String(body.action || "list").toLowerCase();
const query = String(body.query || "").trim();
const limit = Math.min(Math.max(Number(body.limit || 20), 1), 200);

let selected = contacts;
if (action === "search" && query) {
  const needle = query.toLowerCase();
  selected = contacts.filter((item) => {
    const hay = [item.name, item.organization, item.title].concat(item.emails, item.phones);
    return hay.some((value) => String(value || "").toLowerCase().indexOf(needle) >= 0);
  });
}

const shown = selected.slice(0, limit).map((item) => {
  const card = { name: item.name, emails: item.emails.slice(0, 3), phones: item.phones.slice(0, 3) };
  if (item.organization) card.organization = item.organization;
  return card;
});

const reportStatus = Number(($json && $json.statusCode) || 0);
let note = "response received";
if (reportStatus === 401) note = "access denied — check the app password for contacts";
else if (reportStatus === 403) note = "address book rejected the request";
else if (reportStatus !== 207) note = "code " + reportStatus;

return [{ json: {
  action: action,
  query: query,
  total: contacts.length,
  matched: selected.length,
  returned: shown.length,
  truncated: selected.length > shown.length,
  listStatus: Number(list.listStatus || 0),
  reportStatus: reportStatus,
  note: note,
  contacts: shown
} }];
